      completed,
      undefined,
      undefined,
      toolCallContext([
        { id: "coder-mixed", name: CODER_OUTPUT_TOOL_NAME },
        { id: "sibling", name: "read" },
      ]),
    ),
    /Coder output must be the sole final tool call/,
  );
});

