          id,
          output,
          undefined,
          undefined,
          toolCallContext([{ id, name: FIXER_OUTPUT_TOOL_NAME }]),
        );
        if (legal) assert.deepEqual((await execution).details, output);
        else await assert.rejects(execution, /phase permits|planned output forbids/);
      }
    }
  }
});

