if [[ "$path" == *"/pulls/3"* && "$path" != *reviews* && "$path" != *comments* ]]; then
  http '{"number":3,"state":"open","head":{"sha":"deadbeef"},"html_url":"https://github.com/acme/widgets/pull/3","updated_at":"2024-01-01T00:00:00Z"}'; exit 0
