          tokenSize: { min: 1000, max: 1000 },
        });
        const previousExit = process.exitCode;
        process.exitCode = undefined;
        try {
          await withInProcessPi({
            cwd: consumer,
            agentDir,
            faux,
            modelsPath: null,
            // Load only the installed packaged entrypoint (default transport).
